    'mn.comandas.modePrint': 'Imprimir', 'mn.comandas.modePrintDesc': 'Se imprime un tique en una o varias impresoras (cocina, sala...). Configura los perfiles abajo.',
    'mn.comandas.howItWorksTitle': '¿Cómo funciona?', 'mn.comandas.howItWorks1': 'Cada vez que se "marcha" un plato a cocina o barra, se abre automáticamente una pequeña ventana con el vale y se lanza el diálogo de impresión de tu navegador — no hace falta ningún programa adicional.',
    'mn.comandas.howItWorks2': 'Cada perfil de impresora de aquí abajo corresponde a un dispositivo/pestaña con su propia impresora predeterminada: configura uno por cada punto físico donde tengas una impresora térmica conectada (cocina, barra, sala...), e indica qué debe imprimir cada uno.',
    'mn.comandas.howItWorks3': 'Truco: configura esa impresora como predeterminada en el dispositivo donde la uses para que cada vale se imprima solo, sin tener que elegirla cada vez. Usa el botón "Probar impresión" de cada perfil antes de empezar a trabajar con clientes.',
