    'gate.cloudError.anon': '⚠️ Falta activar el inicio de sesión "Anónimo" en tu proyecto de Firebase (paso "Activa el inicio de sesión Anónimo" de la guía de aquí abajo): Authentication → Método de acceso → Anónimo → activar y guardar.', 'gate.cloudError.domain': '⚠️ La dirección desde la que estás abriendo la app no está autorizada en tu Firebase. Añádela en Authentication → Settings → Dominios autorizados.', 'gate.cloudError.apikey': '⚠️ La clave de API no es válida. Vuelve a copiarla del paso "Crea una app web y copia tus datos" de la guía de aquí abajo, sin espacios ni comillas.', 'gate.cloudError.network': '⚠️ No hay conexión a internet. Los datos se guardan en este dispositivo y se sincronizarán solos al recuperarla.', 'gate.cloudError.rules': '⚠️ Tu nube te rechaza. Casi siempre es una de estas dos cosas: (1) no pegaste las reglas de seguridad — están en el paso "Pega las reglas de seguridad" de la guía de aquí abajo, y van en Realtime Database → Reglas → Publicar; o (2) la URL de la base de datos que pegaste no es la de este proyecto. Comprueba primero la URL de aquí abajo.',
