    'idr.chatHelloDish': 'Digues quin plat vols crear i et dono opcions: "un entrant de tardor", "alguna cosa amb carbassa per al menú", "un peix a la brasa". Et proposo camins diferents, amb el perquè de cadascun, i el tanquem fins a tenir la recepta sencera.',
    'idr.chatHelloBase': "Digues què vols tenir fet per endavant — un fons, una salsa mare, una crema — i per a què el faràs servir. Et dono opcions. Només necessito que acabem sabent quant en surt (per exemple 3 L) per poder costejar-ho bé.",
