    'mn.pedidos.minOrder': 'Comanda mínima (€)', 'mn.pedidos.minOrderDesc': 'Import mínim de la comanda (sense comptar l\'enviament) per poder-la fer en línia. Posa 0 per no exigir mínim.', 'mn.pedidos.maxPorFranja': 'Màx. comandes per franja de 30 min', 'mn.pedidos.maxPorFranjaDesc': 'Límit de comandes per emportar/domicili que acceptes en la mateixa franja horària, per no saturar la cuina. Posa 0 per no limitar.', 'mn.pedidos.maxParadasRuta': 'Màx. parades per ruta de repartiment', 'mn.pedidos.maxParadasRutaDesc': 'Quantes comandes com a molt s\'agrupen en una mateixa ruta per a un repartidor. Posa 0 per no limitar.', 'mn.pedidos.ventanaRuta': 'Finestra de temps per agrupar en ruta (min)', 'mn.pedidos.ventanaRutaDesc': 'Només s\'agrupen en la mateixa ruta comandes que hagin entrat dins d\'aquesta diferència de minuts entre elles. Posa 0 per no limitar per temps.',
