    'mn.emailConfirm.title': 'Confirmació, cancel·lació i canvis de reserva per email',
    'mn.emailConfirm.desc': 'En quant una reserva quedi confirmada (sola, o quan li assignis taula a mà), el client rep un email automàtic avisant-lo, amb un enllaç per canviar l\'hora o cancel·lar sense haver-te de trucar. S\'envia des del teu propi compte gratuït d\'EmailJS (emailjs.com) — no cal backend ni cost per a volums normals d\'un sol restaurant. Recomanat: sense això, el client no sap si la seva reserva ha quedat confirmada ni té manera de gestionar-la, i et truquen més i tens més "no shows".',
    'mn.emailConfirm.guideBtn': 'Com ho configuro? Guia pas a pas', 'mn.emailConfirm.guideTitle': 'Com configurar els emails de reserva', 'mn.emailConfirm.guideIntro': 'No cal saber programar. Són 6 passos de copiar i enganxar, 15-20 minuts.', 'mn.emailConfirm.guideDone': 'Entès, ho configuro',
