    'title.cancelOrder': 'Cancel·lar comanda', 'btn.cancelOrder': 'Cancel·lar comanda',
    'msg.confirmCancelOrder': 'Vols cancel·lar aquesta comanda? S\'avisarà el client per email si va deixar la seva adreça.',
    'msg.orderCancelled': 'Comanda cancel·lada', 'audit.cancelledOnlineOrder': 'Ha cancel·lat la comanda online de ${name}', 'audit.reservationCancelledByClient': 'El client ${name} ha cancel·lat la seva pròpia reserva des de la web', 'audit.reservationModifiedByClient': 'El client ${name} ha modificat la seva pròpia reserva des de la web', 'audit.depositConfirmed': 'Senyal de reserva de ${name} pagada i confirmada automàticament', 'audit.reservationDepositNeedsRefund': 'Ha cancel·lat la reserva de ${name}, que tenia una senyal de ${amount} ja cobrada — pendent de tornar', 'msg.reservationDepositNeedsRefund': 'Aquesta reserva tenia una senyal de ${amount} ja cobrada. Recorda tornar-la al client.',
    'mn.redsys.title': 'Pagament en línia amb targeta (TPV virtual)',
    'mn.redsys.desc': 'Permet que els teus clients paguin amb targeta en fer una comanda en línia (per emportar/delivery). El cobrament es fa a través del TPV virtual del teu propi banc (Redsys): els diners arriben directament al teu compte, sense intermediaris.',
    'mn.redsys.checking': 'Comprovant configuració...', 'mn.redsys.merchantCode': 'Codi de comerç (FUC)', 'mn.redsys.terminal': 'Terminal',
    'mn.redsys.secretKey': 'Clau secreta (Signatura)', 'mn.redsys.secretKeyPh': 'Enganxa-la aquí (no es mostrarà de nou)',
    'mn.redsys.secretKeyHint': 'L\'obtens al mòdul d\'administració del teu TPV virtual, dins la web del teu banc.',
    'mn.redsys.realEnv': 'Entorn real (cobraments reals). Desmarcat = mode proves.', 'mn.redsys.configured': 'Configurat',
    'mn.redsys.environment': 'Entorn', 'mn.redsys.envReal': 'real', 'mn.redsys.envTest': 'proves',
    'gate.employeeQuestion': 'Ets empleat/da, no el/la propietari/ària?', 'gate.employeeBody': 'No cal que segueixis aquests passos. Torna enrere, prem "Accés Empleats" i escriu el teu nom, el teu PIN i el codi del negoci: l\'app trobarà el teu restaurant sola. Només si això no funcionés, demana al teu cap la Clau d\'API i la URL de la base de dades (les veu a Núvol → "Canviar la configuració de Firebase"), enganxa-les a sota i prem "Desar i connectar".',
    'gate.cloudIntro': 'Cada negoci té el seu <strong>propi espai al núvol</strong> (gratuït, de Google), separat de la resta. <strong>Aquest pas és obligatori</strong>: sense ell, cada dispositiu (el mòbil del cambrer, la tauleta de cuina, el teu ordinador) guardaria les dades per separat i no es veurien entre ells — les comandes de Sala no arribarien a Cuina, el xat no es compartiria, i les tasques que assignis no les veuria el teu equip al seu dispositiu. Configurar-ho porta 2 minuts i només cal fer-ho una vegada.',
    'gate.externalConnections.title': 'Connexions externes',
    'gate.externalConnections.body': 'Aquest núvol és la primera de diverses "connexions externes" que l\'app pot fer servir — cadascuna és un servei de fora, amb el seu propi compte gratuït (o de pagament si vols) que connectes tu mateix. Les altres són opcionals i les configures quan vulguis des de <strong>El Meu Negoci</strong>: cobrament amb targeta en línia (Redsys) i confirmació automàtica de reserves per email (EmailJS). No cal configurar-les ara — l\'app funciona igual sense elles, només desbloquegen funcions extra quan les connectes.',
    'gate.extConn.stepLabel': 'Connexió opcional ${n} de ${total}',
    'gate.extConn.optional': 'Això és opcional.',
    'gate.extConn.alwaysThere': 'Pots connectar-ho ara mateix o deixar-ho per més tard — sempre estarà disponible a El Meu Negoci → Connexions externes quan vulguis activar-ho.',
    'gate.extConn.nextBtn': 'Següent', 'gate.extConn.finishBtn': 'Entrar a l\'app',
    'gate.extConn.skipHint': 'Pots deixar-ho sense configurar i continuar — no cal fer-ho ara.',
    'gate.seeFullGuide': 'No tens aquestes dades? Veure guia completa (per al propietari)',
    'gate.followSteps': 'Segueix aquests passos:', 'gate.shareWithEmployees': 'Ho compartiràs amb empleats? Llegeix això',
    'gate.businesses': 'Negocis', 'gate.exitSetup': 'Cancel·lar', 'bs.exitAccount': 'Sortir i entrar amb un altre compte', 'gate.setupCloud': 'Configura el teu núvol', 'gate.cloudStepLabel': 'Pas 2 de 3 — Connecta el teu núvol (≈10 minuts, una sola vegada)',
    'gate.nt.step1Title': 'Crea un compte gratis a Netlify', 'gate.nt.step1Body': 'Obre <code>www.netlify.com</code> en una altra pestanya i prem <strong>"Sign up"</strong>. Pots entrar amb el teu compte de Google. És gratis i no demana targeta.',
    'gate.nt.step2Title': 'Tingues els dos arxius junts en una carpeta', 'gate.nt.step2Body': 'En una carpeta del teu ordinador deixa <strong>els dos arxius</strong> de GastroGoan: <code>index.html</code> i <code>reservagastrogoan.html</code>. <strong>No renombris</strong> cap dels dos.',
    'gate.nt.step3Title': 'Arrossega la carpeta a Netlify', 'gate.nt.step3Body': 'A Netlify, ves a <strong>"Sites"</strong> i arrossega la teva carpeta al requadre <strong>"Drag and drop your site output folder here"</strong> (o "Deploys" → "Deploy manually").',
    'gate.nt.step4Title': 'Copia l\'adreça que et dona', 'gate.nt.step4Body': 'En uns segons Netlify publica el lloc i et dona una adreça tipus <code>https://el-teu-lloc.netlify.app</code>. Pots canviar el nom a "Site settings" → "Change site name".',
    'gate.nt.step5Title': 'Obre SEMPRE l\'app des d\'aquesta adreça', 'gate.nt.step5Body': 'A partir d\'ara gestiona l\'app des de <code>https://el-teu-lloc.netlify.app</code>. Com que es diu index.html, s\'obre directament. Només així el QR de reserves i comandes funcionarà de veritat per als teus clients.',
    'gate.nt.notHostedBody': 'Ara mateix estàs obrint l\'app <strong>des d\'un arxiu local</strong>, no des de l\'adreça oficial de GastroGoan. Les reserves/comandes per QR <strong>no funcionaran</strong> fins que obris l\'app des de l\'adreça web que et vam donar en comprar-la.',
    'gate.nt.title': 'Obre l\'app des de la seva adreça web', 'gate.nt.doneBtn': 'Entès — Continuar',
    'gate.apiKeyLabel': 'Clau d\'API (apiKey)', 'gate.dbUrlLabel': 'URL de la base de dades (databaseURL)', 'gate.saveAndConnect': 'Desar i connectar',
    'gate.cloudModalTitle': 'Núvol — Sincronització entre dispositius', 'gate.needLicenseForCloud': 'Activa la teva llicència de GastroGoan per connectar aquest dispositiu al núvol.',
    'gate.licenseActivatedFor': 'Llicència activada per a', 'gate.tenMinutesIntro': 'Trigaràs uns 10 minuts, una sola vegada. Segueix la guia pas a pas i després enganxa aquí les dues dades que et demani al final:',
    'gate.miniStep1': 'Crea un projecte gratis a <code>console.firebase.google.com</code>', 'gate.miniStep2': 'Activa <strong>Realtime Database</strong>',
    'gate.miniStep3': 'Activa l\'inici de sessió <strong>Anònim</strong> a Authentication', 'gate.miniStep4': 'Enganxa les regles de seguretat que t\'indica la guia',
    'gate.miniStep5': 'Copia el teu <code>apiKey</code> i <code>databaseURL</code> i enganxa\'ls sota',
    'gate.miniStep6': 'A <strong>Authentication → Settings → Dominis autoritzats</strong>, afegeix <code>app.gastrogoan.com</code> i <code>reservas.gastrogoan.com</code>. Sense això Firebase rebutja la connexió: de fàbrica només autoritza les seves pròpies adreces.',
    'gate.cloudConnected': 'Aquest negoci està connectat al seu núvol Firebase', 'gate.connectMoreDevices': 'Per connectar més dispositius',
    'gate.testCloudNow': 'Provar el meu núvol ara',
