    'gate.testCloudRunning': 'Provant la connexió amb el teu núvol…',
    'gate.testCloudOk': '✅ El teu núvol funciona. Les dades s\'estan sincronitzant.',
    'gate.testCloudFail': '❌ Continua sense connectar. Mira el motiu que surt aquí dalt.',
    'gate.testCloudSlow': 'Està trigant més del normal. Torna a provar-ho d\'aquí a una estona.',
    'gate.testCloudNoLicense': 'Primer cal activar el negoci amb el seu codi.',
    'msg.folderNameChars': 'El nom d\'una carpeta no pot portar . $ # [ ] ni /. Escriu-lo sense aquests caràcters.',
    'gate.cloudError.anon': '⚠️ Falta activar l\'inici de sessió "Anònim" al teu projecte de Firebase (pas "Activa l\'inici de sessió Anònim" de la guia de sota): Authentication → Mètode d\'accés → Anònim → activar i desar.', 'gate.cloudError.domain': '⚠️ L\'adreça des d\'on obres l\'app no està autoritzada al teu Firebase. Afegeix-la a Authentication → Settings → Dominis autoritzats.', 'gate.cloudError.apikey': '⚠️ La clau d\'API no és vàlida. Torna a copiar-la del pas "Crea una app web i copia les teves dades" de la guia de sota, sense espais ni cometes.', 'gate.cloudError.network': '⚠️ No hi ha connexió a internet. Les dades es guarden en aquest dispositiu i se sincronitzaran soles en recuperar-la.', 'gate.cloudError.rules': '⚠️ El teu núvol et rebutja. Gairebé sempre és una d\'aquestes dues coses: (1) no vas enganxar les regles de seguretat — són al pas "Enganxa les regles de seguretat" de la guia de sota, i van a Realtime Database → Regles → Publicar; o (2) la URL de la base de dades que vas enganxar no és la d\'aquest projecte. Comprova primer la URL de sota.',
    'gate.cloudErrorLong': 'Hi ha un error de connexió amb el teu núvol Firebase: les dades NO s\'estan sincronitzant. Revisa la configuració de sota (clau d\'API i URL de la base de dades).',
    'gate.connectMoreDevicesBody': '(mòbils de cambrers, tauleta de cuina): instal·la GastroGoan en aquest dispositiu i activa la mateixa clau de llicència (${key}). Es sincronitzarà sol, automàticament, sense passos addicionals.',
    'gate.changeFirebaseConfig': 'Canviar la configuració de Firebase', 'gate.emptyToDisconnect': 'Deixa els dos camps buits i desa per desconnectar el núvol d\'aquest negoci.',
