    'mn.verifactu.title': 'VeriFactu (certified invoicing)',
    'mn.verifactu.desc': 'Connect your own account with a VeriFactu-certified invoicing provider so your tickets comply with Spanish tax rules. You contract and pay that provider directly; GastroGoan only connects using your key.',
    'mn.verifactu.howItWorksTitle': 'How does it work?',
    'mn.verifactu.howItWorks1': 'You sign up yourself with the provider of your choice (with your own card, under your tax ID) and they give you an API key.',
    'mn.verifactu.howItWorks2': 'Paste that key here. From then on, every sale is sent automatically to your account with that provider, which returns the seal (hash) and QR code printed on the ticket.',
    'mn.verifactu.enable': 'Enable VeriFactu submission',
    'mn.verifactu.provider': 'Provider', 'mn.verifactu.selectProvider': '— Select a provider —',
