    'mn.verifactu.domain': 'Your Invocash domain',
    'mn.verifactu.domainHint': 'The same one you use to log into your Invocash panel, without "https://" (e.g. yourbusiness.invo.cash).',
    'msg.verifactuMissingDomain': 'Enter your Invocash domain before enabling it.',
    'mn.verifactu.pendingCount': '${n} sales pending confirmation from the provider (will retry automatically).',
    'msg.verifactuMissingFields': 'Select a provider and enter your API key before enabling it.',
    'mn.verifactu.serie': 'This device\'s series', 'mn.verifactu.serieHint': 'Identifies this specific device (e.g. T1, T2, Bar...). If you use GastroGoan on several phones/tablets at once, each one needs a different series so an invoice number is never repeated.',
    'mn.verifactu.draftBadge': 'Coming soon', 'mn.verifactu.draftNotice': 'VeriFactu is not mandatory yet for your business. GastroGoan is already technically ready; you\'ll be able to activate it right here once the regulation requires it.',
    'mn.verifactu.declarationsTitle': 'Compliance declarations', 'mn.verifactu.declarationsDesc': 'Access to the software manufacturer\'s Compliance Declaration and to the VeriFactu submission provider\'s, as required by the regulation.',
