    'msg.folderNameChars': 'A folder name cannot contain . $ # [ ] or /. Please write it without those characters.',
    'gate.cloudError.anon': '⚠️ You need to enable "Anonymous" sign-in in your Firebase project (the "Enable Anonymous sign-in" step of the guide below): Authentication → Sign-in method → Anonymous → enable and save.', 'gate.cloudError.domain': '⚠️ The address you are opening the app from is not authorised in your Firebase. Add it under Authentication → Settings → Authorised domains.', 'gate.cloudError.apikey': '⚠️ The API key is not valid. Copy it again from the "Create a web app and copy your details" step of the guide below, with no spaces or quotes.', 'gate.cloudError.network': '⚠️ No internet connection. Data is saved on this device and will sync on its own once it is back.', 'gate.cloudError.rules': '⚠️ Your cloud is refusing you. It is almost always one of two things: (1) you did not paste the security rules — they are in the "Paste the security rules" step of the guide below, and go into Realtime Database → Rules → Publish; or (2) the database URL you pasted is not the one for this project. Check the URL below first.',
    'gate.cloudErrorLong': 'There is a connection error with your Firebase cloud: data is NOT syncing. Check the configuration below (API key and database URL).',
    'gate.connectMoreDevicesBody': '(waiters\' phones, kitchen tablet): install GastroGoan on that device and activate the same license key (${key}). It will sync automatically, with no extra steps.',
